import { html , render , WebComponent , customElement , attr , attrState , state, css, ViewTemplate, ViewContext, asyncAppend, repeat, children } from '@lithium-framework/core';
import '@lithium-framework/router-element';
import { json } from 'stream/consumers';
import 'unofficial-pf-v5-wc';
import 'unofficial-pf-v5-wc-icons';

@customElement({
  name: 'page-informations',
  template: html`${(information: Information) => {
    return html`
      <pf-page masterhead-no-icon masterhead-no-branding drawer-inline drawer-expanded drawer-static drawer-panel-left>
        <div slot="drawer-panel">
          <pf-navigation>
            <pf-navigation-list>
              <pf-navigation-list-item @mousedown=${() => { window.location.href = "cours" }}>Cours</pf-navigation-list-item>
              <pf-navigation-list-item @mousedown=${() => { window.location.href = "informations" }}>Informations supplémentaires</pf-navigation-list-item>
              <pf-navigation-list-item @mousedown=${() => { window.location.href = "compte" }}>Compte</pf-navigation-list-item>
              <pf-navigation-list-item @mousedown=${() => { window.location.href = "profile" }}>Profile</pf-navigation-list-item>
            </pf-navigation-list>
          </pf-navigation>
        </div>
        <div>
          <pf-panel header scrollable>
            <h1 slot="header">Informations</h1>
            <div class="table-infos">
              ${asyncAppend(information.preloadData(), (result) => {
                  return html`${
                    repeat(
                      result,
                      (info) => html`
                        <div class="row">
                          <div class="type-de-cours">${info.date_of_birth}</div>
                          <div class="heure-debut">${info.email}</div>
                          <div class="heure-fin">${info.first_name}</div>
                          <div class="type-de-cours">${info.gender}</div>
                          <div class="heure-debut">${info.grade}</div>
                          <div class="heure-fin">${info.last_name}</div>
                          <div class="heure-fin">${info.role}</div>
                        </div>`
                    )
                  }`
                })
              }
            </div>
          </pf-panel>
        </div>
        <pf-avatar></pf-avatar>
      </pf-page>`;
  }}`
})

export class Information extends WebComponent {
  data: any[] = [];

  async connectedCallback() {
    super.connectedCallback();
    try {
      const newData = await this.preloadData();
      console.log(newData.length)
      if (newData.length > 0) {
        // Vérifie que les données sont correctes
        console.log('Nouvelles données reçues :', newData);

        // Assigne les nouvelles données
        this.data = [...newData]; // Utilise le spread pour assigner les données
        console.log('Données assignées à this.data :', this.data);
      }
    } catch (error) {
      console.error('Erreur lors de la récupération et l\'assignation des données:', error);
    }
  }

  async preloadData(): Promise<any[]> {
    try {
      const userDataString = localStorage.getItem('userData');
      if (!userDataString) {
        throw new Error('Utilisateur non connecté. Aucune donnée dans localStorage.');
      }
  
      const userData = JSON.parse(userDataString);
      console.log('Données utilisateur récupérées:', userData);
  
      const response = await fetch('http://localhost:3000/informations', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(userData),
      });
  
      if (!response.ok) {
        throw new Error('Erreur serveur.');
      }
  
      const data = await response.json();
      console.log('Réponse du serveur:', data); // <-- Ajoute ce log pour voir les données renvoyées par le serveur
  
      return data.length > 0 ? data : [];
    } catch (error) {
      console.error('Erreur lors de la requête fetch:', error);
      return [];
    }
  }  
}



let template: ViewTemplate<any> = html`${( context:ViewContext )=>{


  return html`<page-informations></page-informations>`;

}}`




render(template);